import { Bot, User, Check, X, Download, ChevronDown, ChevronUp } from "lucide-react";
import ReactMarkdown from "react-markdown";
import { useState } from "react";

function LogsBlock({ logs }) {
  const [open, setOpen] = useState(false);
  if (!logs?.length) return null;
  return (
    <div className="logs-block">
      <button className="logs-toggle" onClick={() => setOpen((o) => !o)}>
        {open ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
        {open ? "Hide" : "Show"} logs ({logs.length})
      </button>
      {open && (
        <div className="logs-list">
          {logs.map((l, i) => (
            <div key={i} className="log-line">{l}</div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function ChatWindow({
  activeChat,
  chatEndRef,
  onFeedback,
  feedbackPending,
  isLoadingChat,
}) {
  return (
    <div className="chat">
      {activeChat?.messages.map((msg, index) => (
        <div
          key={index}
          className={`message-row ${msg.sender === "user" ? "row-user" : "row-bot"}`}
        >
          {msg.sender === "bot" && (
            <div className="avatar avatar-bot">
              <Bot size={16} />
            </div>
          )}

          <div
            className={`message ${msg.sender === "user" ? "message-user" : "message-bot"}`}
          >
            {/* Message text */}
            {msg.sender === "bot" ? (
              <ReactMarkdown
                components={{
                  p: ({ children }) => (
                    <p style={{ margin: "4px 0", whiteSpace: "pre-wrap" }}>{children}</p>
                  ),
                  ul: ({ children }) => (
                    <ul style={{ paddingLeft: "16px", margin: "4px 0" }}>{children}</ul>
                  ),
                  li: ({ children }) => <li style={{ margin: "2px 0" }}>{children}</li>,
                }}
              >
                {msg.text}
              </ReactMarkdown>
            ) : (
              <p style={{ whiteSpace: "pre-wrap" }}>{msg.text}</p>
            )}

            {/* Inline list (initial bot message) */}
            {msg.list && (
              <ul>
                {msg.list.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ul>
            )}

            {/* Step badge */}
            {msg.stepName && (
              <div className="step-badge">
                🔧 {msg.stepName}
              </div>
            )}

            {/* Collapsible logs */}
            <LogsBlock logs={msg.logs} />

            {/* Human-in-the-loop feedback buttons */}
            {msg.awaitsFeedback && !msg.feedbackDone && (
              <div className="feedback-bar">
                <span className="feedback-label">Apply this step?</span>
                <button
                  className="btn-feedback btn-accept"
                  disabled={isLoadingChat || !feedbackPending}
                  onClick={() => onFeedback(true)}
                >
                  <Check size={13} />
                  Accept
                </button>
                <button
                  className="btn-feedback btn-reject"
                  disabled={isLoadingChat || !feedbackPending}
                  onClick={() => onFeedback(false)}
                >
                  <X size={13} />
                  Reject
                </button>
              </div>
            )}

            {/* Consumed feedback state */}
            {msg.awaitsFeedback && msg.feedbackDone && (
              <div className="feedback-done">
                {msg.feedbackChoice === true
                  ? <><Check size={12} /> Accepted</>
                  : <><X size={12} /> Rejected</>}
              </div>
            )}

            <span className="msg-time">{msg.time}</span>
          </div>

          {msg.sender === "user" && (
            <div className="avatar avatar-user">
              <User size={16} />
            </div>
          )}
        </div>
      ))}
      <div ref={chatEndRef} />
    </div>
  );
}
